def fixture(padded=False, revision=3):
    """Generated bytes exercise format rules; they are not a genuine game save."""
    header = bytearray(parser.HEADER_SIZE)
    header[:16] = bytes.fromhex('61657243020100020300040002020000')
    struct.pack_into('<I', header, 8, 0x40000 + revision)
    header[0x40:0x55] = b'unknown-header-bytes!'
    header[0xCD:0xD9] = b'Builder\0\0\0\0\0'
    body = bytearray(parser.BODY_SIZE)
    for base, count in ((parser.POCKET_BASE, parser.POCKET_COUNT),
                        (parser.BAG_BASE, parser.BAG_COUNT)):
        for index in range(count):
            struct.pack_into('<HH', body, base + index * 4, 2, 10 + index % 20)
    struct.pack_into('<HH', body, parser.POCKET_BASE + 4, 16, 8)
    struct.pack_into('<HH', body, parser.POCKET_BASE + 8, 1819, 25)
    # Distinctive equipment and world bytes must survive every edit.
    body[0x55B959:0x55B999] = bytes(range(64))
    body[0x130:0x170] = bytes(range(64, 128))
    compressed = zlib.compress(body, 1)
    used = parser.HEADER_SIZE + len(compressed)
    struct.pack_into('<I', header, 0x10, used)
    raw = bytes(header) + compressed
    if padded:
        raw += bytes(parser.PADDED_SIZE - len(raw))
        raw = raw[:-33] + b'preserve-unused-nonzero-capacity!'
    return raw


class Dqb2ContractTests(ScalarContractTests, unittest.TestCase):
    game_id = parser.GAME_ID

    def fixture_bytes(self):
        return fixture()

    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.addCleanup(self.temporary.cleanup)
        self.folder = Path(self.temporary.name)
        self.game = SimpleNamespace(extension=parser.EXTENSION)
        self.adapter = BoundScalarAdapter(parser.GAME_ID, parser.EXTENSION, parser)
        self.raw = fixture()
        self.source = self.folder / 'input-copy.bin'
        self.source.write_bytes(self.raw)
        self.document = self.adapter.read_save(self.source)


class Dqb2FormatTests(unittest.TestCase):
    def test_compact_and_padded_unchanged_roundtrips_both_revisions(self):
        for padded in (False, True):
            for revision in (3, 4):
                with self.subTest(padded=padded, revision=revision):
                    raw = fixture(padded, revision)
                    document = parser.decode(raw)
                    self.assertEqual(len(document.payload), parser.BODY_SIZE)
                    self.assertEqual(parser.serialize(document, {}), raw)
                    self.assertTrue(parser.fields_for(document))
                    self.assertEqual(len(parser.item_records(document)), 435)
                    self.assertEqual(len(parser.player_records(document)), 11)

    def test_all_fields_batch_changes_only_quantities_not_ids_equipment_or_world(self):
        for padded in (False, True):
            raw = fixture(padded)
            document = parser.decode(raw)
            fields = parser.fields_for(document)
            changes = {field.id: 1 for field in fields}
            output = parser.serialize(document, changes)
            reopened = parser.decode(output)
            touched = {i for i, (before, after) in enumerate(zip(document.payload, reopened.payload))
                       if before != after}
            allowed = {i for field in fields for i in range(field.offset, field.offset + field.size)}
            self.assertTrue(touched)
            self.assertLessEqual(touched, allowed)
            self.assertEqual(reopened.payload, parser.changed_payload(document, changes))
            for field in fields:
                self.assertEqual(field.value(reopened.payload), 1)
            self.assertEqual(parser.player_records(reopened), parser.player_records(document))
            self.assertEqual(output[:0x10], raw[:0x10])
            self.assertEqual(output[0x14:parser.HEADER_SIZE], raw[0x14:parser.HEADER_SIZE])
            old_used = int.from_bytes(raw[0x10:0x14], 'little')
            if padded:
                self.assertEqual(len(output), len(raw))
                self.assertEqual(output[old_used:], raw[old_used:])
                self.assertEqual(output[-32:], raw[-32:])
            else:
                self.assertEqual(len(output), int.from_bytes(output[0x10:0x14], 'little'))

    def test_single_field_stage_unstage_and_review(self):
        document = parser.decode(fixture())
        changes = parser.stage(document, {}, 'pockets_1', 3)
        field = parser.field_map(document)['pockets_1']
        self.assertEqual(parser.review(document, changes), [(field, 10, 3)])
        self.assertEqual(parser.stage(document, changes, 'pockets_1', 10), {})
        self.assertEqual(changes, {'pockets_1': 3})
        output = parser.decode(parser.serialize(document, changes)).payload
        self.assertEqual(output[:field.offset], document.payload[:field.offset])
        self.assertEqual(output[field.offset + field.size:], document.payload[field.offset + field.size:])

    def test_ineligible_unknown_empty_single_and_unusual_records_preserved(self):
        raw = fixture()
        document = parser.decode(raw)
        body = bytearray(document.payload)
        examples = ((0, 20), (65535, 20), (2, 0), (2, 1), (2, 1000), (2, 65535))
        for index, (item_id, quantity) in enumerate(examples):
            struct.pack_into('<HH', body, parser.BAG_BASE + index * 4, item_id, quantity)
        compressed = zlib.compress(body, 1)
        header = bytearray(raw[:parser.HEADER_SIZE])
        struct.pack_into('<I', header, 0x10, len(header) + len(compressed))
        raw = bytes(header) + compressed
        document = parser.decode(raw)
        mapping = parser.field_map(document)
        for index in range(len(examples)):
            self.assertNotIn(f'bag_{index + 1}', mapping)
            with self.assertRaises(SaveError):
                parser.stage(document, {}, f'bag_{index + 1}', 1)
        self.assertEqual(parser.serialize(document, {}), raw)
        changed = parser.decode(parser.serialize(document, {'pockets_1': 3}))
        self.assertEqual(changed.payload[parser.BAG_BASE:parser.BAG_BASE + len(examples) * 4],
                         document.payload[parser.BAG_BASE:parser.BAG_BASE + len(examples) * 4])

    def test_zero_increase_bool_float_text_and_unknown_changes_rejected(self):
        document = parser.decode(fixture())
        for value in (-1, 0, 11, 999, True, False, '3', 3.0, None):
            for operation in (parser.stage, parser.serialize):
                with self.subTest(value=value, operation=operation.__name__), self.assertRaises(SaveError):
                    if operation is parser.stage:
                        operation(document, {}, 'pockets_1', value)
                    else:
                        operation(document, {'pockets_1': value})
        for key in ('level', 'fullness', 'name', 'story', 'equipment', 'gratitude', 'pockets_0', 'bag_421'):
            with self.assertRaises(SaveError):
                parser.serialize(document, {key: 1})
        for bad in (None, [], {'pockets_1': True}):
            with self.assertRaises(SaveError):
                parser.changed_payload(document, bad)
        self.assertEqual(parser.maximums(document, {}), {})
        self.assertEqual(parser.maximums(document, {'pockets_1': 3}), {'pockets_1': 3})
        self.assertEqual(parser.limit_values(document, {}, ['pockets_1']), {})
        with self.assertRaises(SaveError):
            parser.limit_values(document, {}, ['unknown'])

    def test_native_header_revision_used_extent_and_mutable_inputs_rejected(self):
        raw = fixture()
        for offset in (0, 4, 5, 7, 8, 10, 12, 14):
            damaged = bytearray(raw)
            damaged[offset] ^= 0x80
            with self.subTest(offset=offset), self.assertRaises(SaveError):
                parser.decode(bytes(damaged))
        for used in (0, parser.HEADER_SIZE, parser.HEADER_SIZE + 1, len(raw) + 1, 0xFFFFFFFF):
            damaged = bytearray(raw)
            struct.pack_into('<I', damaged, 0x10, used)
            with self.assertRaises(SaveError):
                parser.decode(bytes(damaged))
        for bad in (raw[:-1], raw + b'\0', b'\0' * len(raw), bytearray(raw), memoryview(raw)):
            with self.assertRaises(SaveError):
                parser.decode(bad)
        with self.assertRaises(SaveError):
            parser.decode(raw, 'dqb2_switch')

    def test_adler_corruption_trailing_member_short_body_and_zlib_bomb_rejected(self):
        raw = fixture()
        for offset in (parser.HEADER_SIZE, parser.HEADER_SIZE + 2, len(raw) - 1):
            damaged = bytearray(raw)
            damaged[offset] ^= 1
            with self.subTest(offset=offset), self.assertRaises(SaveError):
                parser.decode(bytes(damaged))
        for body in (b'\0' * (parser.BODY_SIZE - 1), b'\0' * (parser.BODY_SIZE + 1), b'\0' * (parser.BODY_SIZE * 2)):
            compressed = zlib.compress(body)
            header = bytearray(raw[:parser.HEADER_SIZE])
            struct.pack_into('<I', header, 0x10, len(header) + len(compressed))
            with self.assertRaises(SaveError):
                parser.decode(bytes(header) + compressed)
        for trailer in (b'\0', zlib.compress(b'extra member')):
            damaged = bytearray(raw + trailer)
            struct.pack_into('<I', damaged, 0x10, len(damaged))
            with self.assertRaises(SaveError):
                parser.decode(bytes(damaged))

    def test_forged_document_mutable_alias_and_original_payload_mismatch_rejected(self):
        document = parser.decode(fixture())
        for forged in (replace(document, raw=bytearray(document.raw)),
                       replace(document, payload=bytearray(document.payload)),
                       replace(document, payload=document.payload[:-1] + b'\x01'),
                       replace(document, format=replace(document.format, id='wrong'))):
            with self.assertRaises(SaveError):
                parser.serialize(forged, {})
        self.assertEqual(parser.serialize(document, {}), document.raw)

    def test_padded_growth_guard_and_opaque_tail(self):
        raw = fixture(True)
        document = parser.decode(raw)
        original_used = int.from_bytes(raw[0x10:0x14], 'little')
        with patch.object(parser.zlib, 'compress', return_value=b'x' * (original_used - parser.HEADER_SIZE + 1)):
            with self.assertRaisesRegex(SaveError, 'overwrite original unused data'):
                parser.serialize(document, {'pockets_1': 3})
        self.assertEqual(parser.serialize(document, {}), raw)

    def test_backup_restore_changed_source_existing_aliases_and_corrupt_backup(self):
        with tempfile.TemporaryDirectory() as directory:
            folder = Path(directory)
            source = folder / 'CMNDAT.BIN'
            raw = fixture(True)
            source.write_bytes(raw)
            document = parser.read_save(source)
            snapshot = parser.backup(document)
            restored = folder / 'restored.bin'
            self.assertEqual(parser.restore(snapshot, restored).read_bytes(), raw)
            output = folder / 'edited.bin'
            saved = parser.save_as(document, {'pockets_1': 3}, output)
            self.assertEqual(parser.field_map(saved)['pockets_1'].value(saved.payload), 3)
            self.assertEqual(source.read_bytes(), raw)
            for destination in (source, output, folder / '.' / 'CMNDAT.BIN'):
                with self.assertRaises(FileExistsError):
                    parser.save_as(document, {}, destination)
            bad = bytearray(snapshot.read_bytes())
            bad[-33] ^= 1
            snapshot.write_bytes(bad)
            with self.assertRaises(SaveError):
                parser.restore(snapshot, folder / 'corrupt-restore.bin')
            source.write_bytes(raw[:-1] + bytes([raw[-1] ^ 1]))
            with self.assertRaises(SaveError):
                parser.save_as(document, {}, folder / 'changed-source.bin')
            self.assertFalse((folder / 'changed-source.bin').exists())

    def test_checksum_valid_foreign_backup_rejected_before_write(self):
        with tempfile.TemporaryDirectory() as directory:
            folder = Path(directory)
            source = folder / 'CMNDAT.BIN'
            source.write_bytes(fixture())
            snapshot = parser.backup(parser.read_save(source))
            bad = bytearray(snapshot.read_bytes())
            bad[8] = 99
            snapshot.write_bytes(bad)
            metadata_path = snapshot.with_suffix('.json')
            metadata = json.loads(metadata_path.read_bytes())
            metadata['sha256'] = hashlib.sha256(bad).hexdigest()
            metadata_path.write_text(json.dumps(metadata))
            destination = folder / 'foreign-restore.bin'
            with self.assertRaises(SaveError):
                parser.restore(snapshot, destination)
            self.assertFalse(destination.exists())

    def test_live_folder_lexical_and_resolved_aliases_are_rejected(self):
        with tempfile.TemporaryDirectory() as directory:
            folder = Path(directory)
            raw = fixture()
            copied = folder / 'SeparateCopies' / 'CMNDAT.BIN'
            copied.parent.mkdir()
            copied.write_bytes(raw)
            document = parser.read_save(copied)
            snapshot = parser.backup(document)
            for title in ('DRAGON QUEST BUILDERS II', 'DRAGON QUEST BUILDERS 2',
                          'ドラゴンクエストビルダーズ２'):
                live = folder / 'Documents' / 'My Games' / title / 'Steam' / 'owner' / 'SD' / 'B00' / 'CMNDAT.BIN'
                live.parent.mkdir(parents=True)
                live.write_bytes(raw)
                for action in (lambda: parser.read_save(live),
                               lambda: parser.save_as(document, {}, live.parent / 'new.bin'),
                               lambda: parser.restore(snapshot, live.parent / 'restore.bin'),
                               lambda: parser.restore(live, folder / 'invalid-restore.bin')):
                    with self.assertRaises(SaveError):
                        action()
                self.assertEqual(live.read_bytes(), raw)
            alias = folder / 'alias.bin'
            try:
                alias.symlink_to(live)
            except OSError:
                pass  # Windows CI may not grant symlink creation privileges.
            else:
                with self.assertRaises(SaveError):
                    parser.read_save(alias)

    def test_malformed_field_keys_and_limit_selectors_are_rejected(self):
        document = parser.decode(fixture())
        for key in ([], {}, None, 1, True, ('pockets_1',)):
            with self.assertRaises(SaveError):
                parser.stage(document, {}, key, 1)
        for keys in (None, 1, 'pockets_1', [[]], [True], [{}], ('unknown',)):
            with self.assertRaises(SaveError):
                parser.limit_values(document, {}, keys)

    def test_optional_native_files_all_fields_surgical_roundtrips_and_safe_storage(self):
        setting = os.environ.get('DQB2_PC_SAVE_COPIES')
        if not setting:
            self.skipTest('No private native DQB2 Steam CMNDAT copies supplied.')
        paths = [p for entry in setting.split(os.pathsep)
                 for p in ([Path(entry)] if Path(entry).is_file() else Path(entry).rglob('CMNDAT.BIN'))]
        self.assertTrue(paths)
        edited_native_files = 0
        for original in paths:
            with self.subTest(sample=original.name), tempfile.TemporaryDirectory() as directory:
                folder = Path(directory)
                raw = original.read_bytes()
                source = folder / 'CMNDAT.BIN'
                source.write_bytes(raw)
                document = parser.read_save(source)
                self.assertEqual(parser.serialize(document, {}), raw)
                fields = parser.fields_for(document)
                changes = {field.id: 1 for field in fields}
                output = parser.serialize(document, changes)
                reopened = parser.decode(output)
                allowed = {i for field in fields for i in range(field.offset, field.offset + field.size)}
                touched = {i for i, (a, b) in enumerate(zip(document.payload, reopened.payload)) if a != b}
                self.assertLessEqual(touched, allowed)
                self.assertEqual(parser.player_records(reopened), parser.player_records(document))
                if changes:
                    edited_native_files += 1
                    saved = parser.save_as(document, changes, folder / 'edited.bin')
                    self.assertEqual(saved.payload, reopened.payload)
                snapshot = parser.backup(document)
                self.assertEqual(parser.restore(snapshot, folder / 'restored.bin').read_bytes(), raw)
                self.assertEqual(source.read_bytes(), raw)
                self.assertEqual(original.read_bytes(), raw)
        self.assertGreater(edited_native_files, 0, 'Native write qualification requires an existing editable stack.')

    def test_actual_tk_named_search_undo_review_save_as_backup_and_restore(self):
        try:
            import tkinter as tk
            root = tk.Tk()
        except Exception as error:
            self.skipTest('Tk display unavailable: ' + type(error).__name__)
        self.addCleanup(root.destroy)
        from koei_editor.games.dqb2_pc.editor import Editor
        with tempfile.TemporaryDirectory() as directory:
            folder = Path(directory)
            source = folder / 'CMNDAT.BIN'
            raw = fixture(True)
            setting = os.environ.get('DQB2_PC_SAVE_COPIES')
            if setting:
                candidates = [p for entry in setting.split(os.pathsep)
                              for p in ([Path(entry)] if Path(entry).is_file() else Path(entry).rglob('CMNDAT.BIN'))]
                raw = next((p.read_bytes() for p in candidates if parser.fields_for(parser.decode(p.read_bytes()))), raw)
            source.write_bytes(raw)
            fields = parser.fields_for(parser.decode(raw))
            selected = fields[0]
            pending = {field.id: min(3, field.maximum - 1) for field in fields[:2]}
            editor = Editor(root, parent=root)
            with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename', return_value=str(source)):
                editor.open()
            root.update()
            self.assertEqual(len(editor.fields.get_children()), len(fields))
            editor.search.set(selected.label.removesuffix(' quantity'))
            root.update()
            self.assertIn(selected.id, editor.fields.get_children())
            editor.search.set('')
            editor.stage_values(pending)
            self.assertEqual(len(parser.review(editor.document, editor.changes)), len(pending))
            editor.undo()
            self.assertEqual(editor.changes, {})
            pending = {selected.id: min(3, selected.maximum - 1)}
            editor.stage_values(pending)
            before = set(root.winfo_children())
            editor.review()
            root.update()
            dialogs = [x for x in root.winfo_children() if x not in before and isinstance(x, tk.Toplevel)]
            self.assertEqual(len(dialogs), 1)
            dialogs[0].destroy()
            destination = folder / 'edited.bin'
            with patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename', return_value=str(destination)):
                editor.save_as()
            saved = parser.read_save(destination)
            self.assertEqual(selected.value(saved.payload), pending[selected.id])
            self.assertEqual(source.read_bytes(), raw)
            snapshots = [p for p in (folder / 'UniversalEditorBackups').iterdir()
                         if p.suffix.lower() == '.bin']
            self.assertTrue(snapshots)
            self.assertEqual(parser.restore(snapshots[0], folder / 'gui-restored.bin').read_bytes(), raw)


